# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'

MAX_GUESSES = 9


def _mask(word, guessed):
    return ''.join(c if c in guessed else '_' for c in word)


def _status(word, guessed, remaining_guesses):
    if all(c in guessed for c in word):
        return STATUS_WIN
    if remaining_guesses == 0:
        return STATUS_LOSE
    return STATUS_ONGOING


class Hangman:
    def __init__(self, word):
        self._word = word
        self._guessed = set()
        self.remaining_guesses = MAX_GUESSES
        self.status = STATUS_ONGOING

    def guess(self, char):
        if self.status != STATUS_ONGOING:
            raise ValueError("The game has already ended.")

        if char not in self._guessed and char in self._word:
            self._guessed.add(char)
        else:
            self.remaining_guesses -= 1

        self.status = _status(self._word, self._guessed, self.remaining_guesses)

    def get_masked_word(self):
        return _mask(self._word, self._guessed)

    def get_status(self):
        return self.status

